#define _XOPEN_SOURCE 700

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "fileio.h"
#include "platform.h"
#include "settings.h"
#include "util.h"

/* The words of the file: fixed, independent of the language. */
static const char *const theme_words[THEME_COUNT] = {
	"auto", "system", "light", "dark"
};

void settings_default(struct settings *s)
{
	s->theme = THEME_AUTO;
}

static int same_word(const char *word, const char *text, size_t len)
{
	return strlen(word) == len && memcmp(word, text, len) == 0;
}

/* Sets value of key; unknown keys and values are left as they are. */
static void settings_set(struct settings *s, const char *key, size_t klen,
    const char *value, size_t vlen)
{
	size_t i;

	if (same_word("theme", key, klen)) {
		for (i = 0; i < THEME_COUNT; i++)
			if (same_word(theme_words[i], value, vlen))
				s->theme = (enum theme)i;
	}
}

static int blank(int c)
{
	return c == ' ' || c == '\t' || c == '\r';
}

/*
 * Lines of "key=value", blanks around both ignored; "#" starts a
 * comment line. What the file does not say stays as it was.
 */
void settings_parse(struct settings *s, const char *data, size_t len)
{
	const char *line = data, *end = data + len, *eol, *eq, *k, *ke, *v, *ve;

	while (line < end) {
		eol = memchr(line, '\n', (size_t)(end - line));
		if (eol == NULL)
			eol = end;
		eq = memchr(line, '=', (size_t)(eol - line));
		for (k = line; k < eol && blank(*k); k++)
			;
		if (eq != NULL && *k != '#') {
			for (ke = eq; ke > k && blank(ke[-1]); ke--)
				;
			for (v = eq + 1; v < eol && blank(*v); v++)
				;
			for (ve = eol; ve > v && blank(ve[-1]); ve--)
				;
			settings_set(s, k, (size_t)(ke - k), v, (size_t)(ve - v));
		}
		line = eol + 1;
	}
}

char *settings_text(const struct settings *s)
{
	const char *theme = theme_words[s->theme];
	char *text;
	size_t cap;

	cap = strlen(theme) + 16;
	text = xmalloc(cap);
	snprintf(text, cap, "theme=%s\n", theme);
	return text;
}

/* The file next to the trash; NULL when there is no home to put it in. */
char *settings_path(const char *home)
{
	char *dir, *path;

	dir = platform_data_dir(home);
	if (dir == NULL)
		return NULL;
	path = xjoin(dir, "settings");
	free(dir);
	return path;
}

/* Defaults, then the file; a missing file is no error. */
int settings_load(const char *path, struct settings *s)
{
	char *data;
	size_t len;

	settings_default(s);
	if (path == NULL)
		return 0;
	if (file_read(path, &data, &len) != 0)
		return errno == ENOENT ? 0 : -1;
	settings_parse(s, data, len);
	free(data);
	return 0;
}

/* Replaces the file whole, creating its directory when needed. */
int settings_save(const char *path, const struct settings *s)
{
	char *text;
	int r, saved;

	if (path == NULL) {
		errno = ENOENT;
		return -1;
	}
	text = settings_text(s);
	r = file_store(path, text, strlen(text));
	saved = errno;
	free(text);
	errno = saved;
	return r;
}

/*
 * COLORFGBG, set by rxvt and some others: "fg;bg" or "fg;default;bg".
 * Of the 16 colours, 0-6 and 8 are dark backgrounds. 1 dark, 0 light,
 * -1 when the variable says nothing.
 */
int background_dark(const char *colorfgbg)
{
	const char *p;
	char *end;
	long bg;

	if (colorfgbg == NULL || (p = strrchr(colorfgbg, ';')) == NULL)
		return -1;
	p++;
	if (*p < '0' || *p > '9')
		return -1;
	bg = strtol(p, &end, 10);
	if (*end != '\0' || bg > 15)
		return -1;
	return bg <= 6 || bg == 8;
}
